# Tab completion for bxAgents, for PowerShell 5.1 and 7+.
# Generated by tools/generate-completions.bxs from the verb tables in ModuleConfig.bx, do not edit.
# Load it from your profile ($PROFILE):
#   . "<module folder>\completions\bxAgents.ps1"

Register-ArgumentCompleter -Native -CommandName 'bxAgents', 'bxagents' -ScriptBlock {
	param( $wordToComplete, $commandAst, $cursorPosition )

	$verbs = @{
		'add' = 'Add to a project: add <kind> [name] - a tool or an interceptor'
		'build' = 'Build a project into a generated app'
		'chat' = 'Interactive REPL chat with a built agent'
		'clean' = 'Remove a project''s .build/ and dist/ output'
		'deploy' = 'Deploy to a target'
		'doctor' = 'Diagnose the environment and project - runtime, modules, env vars'
		'hash-password' = 'Hash a password for a webui users entry'
		'inspect' = 'Report how the agent is composed: agents, tools, skills, MCP, exposure, env'
		'invoke' = 'Send one message to a built agent, print the response, exit'
		'new' = 'Scaffold a new agent project'
		'package' = 'Package a built project into a .bxa'
		'serve' = 'Serve a built project via boxlang-miniserver'
		'test' = 'Run a project''s own tests/specs via TestBox'
		'help' = 'Show the usage and the list of verbs'
	}
	$options = @{
		'add' = @(
			@{ Name = 'agent'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'args'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'description'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'dry-run'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'force'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'function'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'name'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'no-tui'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'points'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); Dir = $true }
			@{ Name = 'scope'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'yes'; Value = $false; Choices = @(); Dir = $false }
		)
		'build' = @(
			@{ Name = 'environment'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'generatorVersion'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); Dir = $true }
			@{ Name = 'verbose'; Value = $false; Choices = @(); Dir = $false }
		)
		'build:positional' = 'dir'
		'chat' = @(
			@{ Name = 'connect'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'no-tui'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'port'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); Dir = $true }
			@{ Name = 'record'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'server'; Value = $false; Choices = @(); Dir = $false }
		)
		'chat:positional' = 'dir'
		'clean' = @(
			@{ Name = 'force'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); Dir = $true }
		)
		'clean:positional' = 'dir'
		'deploy' = @(
			@{ Name = 'destination'; Value = $true; Choices = @(); Dir = $true }
			@{ Name = 'name'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); Dir = $true }
			@{ Name = 'target'; Value = $true; Choices = @('digitalocean', 'docker', 'ftp', 'local', 'sftp', 'ssh'); Dir = $false }
		)
		'deploy:positional' = 'dir'
		'doctor' = @(
			@{ Name = 'json'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); Dir = $true }
		)
		'doctor:positional' = 'dir'
		'hash-password' = @(
			@{ Name = 'password'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); Dir = $true }
		)
		'inspect' = @(
			@{ Name = 'ascii'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'environment'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'json'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'md'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'no-color'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); Dir = $true }
			@{ Name = 'section'; Value = $true; Choices = @(); Dir = $false }
		)
		'inspect:positional' = 'dir'
		'invoke' = @(
			@{ Name = 'json'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'message'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'port'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); Dir = $true }
			@{ Name = 'server'; Value = $false; Choices = @(); Dir = $false }
		)
		'invoke:positional' = 'dir'
		'new' = @(
			@{ Name = 'app'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'channels'; Value = $true; Choices = @('web', 'api', 'telegram', 'slack', 'discord', 'whatsapp-cloud', 'teams', 'twilio', 'github', 'email', 'signal'); Dir = $false }
			@{ Name = 'class'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'deploy'; Value = $true; Choices = @('docker', 'digitalocean', 'ssh', 'sftp', 'ftp', 'local'); Dir = $false }
			@{ Name = 'description'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'destination'; Value = $true; Choices = @(); Dir = $true }
			@{ Name = 'files'; Value = $true; Choices = @('read', 'all'); Dir = $false }
			@{ Name = 'files-dir'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'forgebox'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'guard'; Value = $true; Choices = @('off', 'flag', 'block'); Dir = $false }
			@{ Name = 'host'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'mcp'; Value = $true; Choices = @('github', 'stripe', 'notion', 'atlassian', 'cloudflare', 'supabase'); Dir = $false }
			@{ Name = 'memory'; Value = $true; Choices = @('cache', 'file'); Dir = $false }
			@{ Name = 'model'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'name'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'no-tui'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'no-wizard'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); Dir = $true }
			@{ Name = 'region'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'registry'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'remote-path'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'repo'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'search'; Value = $true; Choices = @('http', 'brave', 'tavily', 'exa', 'google'); Dir = $false }
			@{ Name = 'skipInstall'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'template'; Value = $true; Choices = @('minimal', 'webui-chat', 'slack-bot', 'telegram-bot', 'github-bot', 'mcp-server', 'scheduled', 'multi-agent'); Dir = $false }
			@{ Name = 'user'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'web-auth'; Value = $true; Choices = @('open', 'key'); Dir = $false }
			@{ Name = 'with'; Value = $true; Choices = @('time', 'fetch', 'search', 'browse', 'files', 'media'); Dir = $false }
			@{ Name = 'wizard'; Value = $false; Choices = @(); Dir = $false }
			@{ Name = 'yes'; Value = $false; Choices = @(); Dir = $false }
		)
		'new:positional' = 'dir'
		'package' = @(
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); Dir = $true }
			@{ Name = 'version'; Value = $true; Choices = @(); Dir = $false }
		)
		'package:positional' = 'dir'
		'serve' = @(
			@{ Name = 'host'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'port'; Value = $true; Choices = @(); Dir = $false }
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); Dir = $true }
		)
		'serve:positional' = 'dir'
		'test' = @(
			@{ Name = 'projectRoot'; Value = $true; Choices = @(); Dir = $true }
		)
		'test:positional' = 'dir'
		'help' = @(
		)
		'help:positional' = 'verbs'
	}
	$globals = @( '--help', '-h', '--version', '-v' )

	# the words typed before the one under the cursor (the command name is the first); an empty word is not in the AST
	$typed = @( $commandAst.CommandElements | ForEach-Object { $_.ToString() } )
	if ( $wordToComplete -ne '' ) {
		$typed = @( $typed | Select-Object -SkipLast 1 )
	}

	function New-BxAgentsResult( [string] $Text, [string] $Tip ) {
		if ( -not $Tip ) { $Tip = $Text }
		[System.Management.Automation.CompletionResult]::new( $Text, $Text, 'ParameterValue', $Tip )
	}

	function Get-BxAgentsDirectories( [string] $Prefix ) {
		foreach ( $item in @( Get-ChildItem -Directory -Path "$Prefix*" -ErrorAction SilentlyContinue ) ) {
			$path = ( Resolve-Path -LiteralPath $item.FullName -Relative ) + [System.IO.Path]::DirectorySeparatorChar
			if ( $path -match '\s' ) { $path = "'$path'" }
			$path
		}
	}

	# bxAgents <verb>
	if ( $typed.Count -le 1 ) {
		if ( $wordToComplete -like '-*' ) {
			foreach ( $g in $globals ) {
				if ( $g -like "$wordToComplete*" ) { New-BxAgentsResult $g }
			}
		} else {
			foreach ( $name in ( @( $verbs.Keys ) | Sort-Object ) ) {
				if ( $name -like "$wordToComplete*" ) { New-BxAgentsResult $name $verbs[ $name ] }
			}
		}
		return
	}

	$verb = $typed[ 1 ]
	$verbOptions = if ( $options.ContainsKey( $verb ) ) { @( $options[ $verb ] ) } else { @() }

	# --flag=<value>
	if ( $wordToComplete -match '^(--[^=]+)=(.*)$' ) {
		$flag = $Matches[ 1 ]
		$part = $Matches[ 2 ]
		$option = $verbOptions | Where-Object { "--$( $_.Name )" -eq $flag } | Select-Object -First 1
		if ( $option -and $option.Choices.Count ) {
			foreach ( $choice in $option.Choices ) {
				if ( $choice -like "$part*" ) { New-BxAgentsResult "$flag=$choice" $choice }
			}
		} elseif ( $option -and $option.Dir ) {
			foreach ( $path in @( Get-BxAgentsDirectories $part ) ) {
				New-BxAgentsResult "$flag=$path" $path
			}
		}
		return
	}

	# --flag
	if ( $wordToComplete -like '-*' ) {
		foreach ( $option in $verbOptions ) {
			$text = if ( $option.Value ) { "--$( $option.Name )=" } else { "--$( $option.Name )" }
			if ( $text -like "$wordToComplete*" ) { New-BxAgentsResult $text }
		}
		foreach ( $g in $globals ) {
			if ( $g -like "$wordToComplete*" ) { New-BxAgentsResult $g }
		}
		return
	}

	# the argument that follows the verb
	switch ( $options[ "${verb}:positional" ] ) {
		'dir' {
			foreach ( $path in @( Get-BxAgentsDirectories $wordToComplete ) ) {
				New-BxAgentsResult $path
			}
		}
		'verbs' {
			foreach ( $name in ( @( $verbs.Keys ) | Sort-Object ) ) {
				if ( $name -like "$wordToComplete*" ) { New-BxAgentsResult $name $verbs[ $name ] }
			}
		}
	}
}
